(function(){'use strict';
const app=window.OpticalBench,C=CatalogCore,defs=OPTICAL_COMPONENTS,$=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const bundled=C.validate(OPTICAL_CATALOG,defs,ComponentPacks).records;
let panel,chosen=null;
function records(){return C.merge(bundled,C.validate({kind:'optical-bench-catalog',version:1,records:app.exportDesign().catalogRecords||[]},defs,ComponentPacks).records)}
function makeFile(name,obj){const u=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function refresh(){try{const all=records(),vendor=$('catalogVendor').value;$('catalogVendor').innerHTML='<option value="">全部厂商</option>'+[...new Set(all.map(r=>r.vendor))].sort().map(v=>'<option>'+esc(v)+'</option>').join('');$('catalogVendor').value=vendor;const matches=C.search(all,{vendor:$('catalogVendor').value,query:$('catalogQuery').value,type:$('catalogType').value});$('catalogCount').textContent=matches.length+' / '+all.length+' 个已收录型号（非厂商完整目录）';$('catalogResults').replaceChildren();for(const r of matches){const b=document.createElement('button');b.className='catalog-item';b.innerHTML='<small>'+esc(r.vendor)+'</small><strong>'+esc(r.sku)+'</strong><span>'+esc(r.name)+'</span>';b.onclick=()=>detail(r);$('catalogResults').append(b)}if(!matches.length)$('catalogResults').textContent='未收录此型号。可导入核实过的器材库 JSON；不会自动用相近型号替代。';}catch(e){$('catalogStatus').textContent=e.message}}
function detail(r){chosen=r;const defaults={...defs[r.baseType].defaults,...r.params};$('catalogDetail').innerHTML='<small>'+esc(r.vendor)+' · '+esc(defs[r.baseType].name)+'</small><h2>'+esc(r.sku)+'</h2><p>'+esc(r.name)+'</p><p><a href="'+esc(C.url(r.source))+'" target="_blank" rel="noopener noreferrer">查看厂商来源 ↗</a> · 核对日期 '+esc(r.checked)+'</p><h3>厂家规格</h3><table>'+r.specs.map(([k,v])=>'<tr><th>'+esc(k)+'</th><td>'+esc(v)+'</td></tr>').join('')+'</table><p class="catalog-note">'+esc(r.notes)+'</p><h3>用于模拟的参数</h3><table><tr><th>参数</th><th>数值</th><th>来源 / 近似</th></tr>'+Object.entries(defaults).map(([k,v])=>'<tr><td>'+esc(app.paramLabels[k]||k)+'</td><td>'+esc(v)+'</td><td>'+esc(r.basis[k]||'未收录：使用通用默认值，需核对')+'</td></tr>').join('')+'</table><p>保留现有光路；添加后可在右侧修改位置和高级模型参数。外形使用通用三维模型。</p><button id="catalogAdd" class="primary">＋ 放入光路</button>';$('catalogAdd').onclick=()=>{if(window.experimentLocked)return;const s=app.exportDesign(),b=s.boards[0],count=s.components.filter(c=>c.catalog).length;const item=C.instantiate(r,defs,s.components,{x:b.x+Math.min(b.cols-1,2+count%Math.max(1,b.cols-3))*b.spacing,y:b.y+Math.min(b.rows-1,2+Math.floor(count/Math.max(1,b.cols-3)))*b.spacing});app.insertCatalogComponent(item);panel.close()};}
function open(type){if(window.experimentLocked)return;if(!panel){panel=document.createElement('dialog');panel.id='catalogPanel';panel.setAttribute('aria-label','厂商器材库');panel.innerHTML='<header><div><small>OPTICAL CATALOG</small><h2>厂商器材库</h2></div><button id="catalogClose">关闭</button></header><p>按厂商和型号选器件，自动填入已收录参数。未收录参数保留通用默认值并标明；本库离线运行，不是实时官网搜索。</p><div class="catalog-controls"><label>厂商<select id="catalogVendor"><option value="">全部厂商</option></select></label><label>搜索型号或名称<input id="catalogQuery" placeholder="如 86-104、LA1509、CX10613-C"></label><label>类型<select id="catalogType"><option value="">全部类型</option>'+Object.entries(defs).map(([k,d])=>'<option value="'+esc(k)+'">'+esc(d.name)+'</option>').join('')+'</select></label></div><div class="catalog-tools"><label class="catalog-import">导入器材库 JSON<input id="catalogImport" type="file" accept=".json"></label><button id="catalogExport">导出当前器材库</button><button id="catalogTemplate">下载导入示例</button></div><p id="catalogCount"></p><p id="catalogStatus" role="status"></p><div class="catalog-layout"><nav id="catalogResults" aria-label="型号列表"></nav><section id="catalogDetail"><h3>选择一个型号</h3><p>这里会显示厂家规格、模拟参数以及尚需核对的数据。</p></section></div>';document.body.append(panel);panel.addEventListener('keydown',e=>e.stopPropagation());$('catalogClose').onclick=()=>panel.close();$('catalogQuery').oninput=refresh;$('catalogVendor').onchange=refresh;$('catalogType').onchange=()=>{refresh();generic()};$('catalogExport').onclick=()=>makeFile('manufacturer-catalog.json',{kind:'optical-bench-catalog',version:1,records:records()});$('catalogTemplate').onclick=()=>makeFile('catalog-import-example.json',{kind:'optical-bench-catalog',version:1,records:[{...bundled[0],vendor:'My Lab',sku:'MY-LENS-001',source:bundled[0].source,notes:'格式示例：请替换型号、来源、规格和参数后导入。此条不代表真实产品。'}]});$('catalogImport').onchange=async e=>{try{if(window.experimentLocked)return;const f=e.target.files[0];if(!f)return;if(f.size>2*1024*1024)throw Error('器材库文件上限 2 MB');const incoming=C.validate(JSON.parse(await f.text()),defs,ComponentPacks).records;const all=records(),fresh=incoming.filter(r=>!all.some(a=>a.vendor.toLowerCase()===r.vendor.toLowerCase()&&a.sku.toLowerCase()===r.sku.toLowerCase()));C.merge(all,fresh);app.setCatalogRecords([...(app.exportDesign().catalogRecords||[]),...fresh]);refresh();$('catalogStatus').textContent='已导入 '+fresh.length+' 个新型号；跳过 '+(incoming.length-fresh.length)+' 个已存在型号（未覆盖）。请保存设计以保留器材库。'}catch(err){$('catalogStatus').textContent='导入失败：'+err.message}finally{e.target.value=''}};}
 $('catalogType').value=type;$('catalogType').disabled=true;$('catalogVendor').value='';$('catalogQuery').value='';$('catalogStatus').textContent='';refresh();generic();panel.showModal();$('catalogQuery').focus();}
function generic(){
 const type=$('catalogType').value;chosen=null;
 $('catalogDetail').innerHTML='<h3>'+esc(defs[type].name)+'</h3><p>选择左侧已收录的厂商型号，或添加通用器件后自行设置参数。</p><button id="genericAdd" class="primary">＋ 添加通用'+esc(defs[type].name)+'</button>';
 $('genericAdd').onclick=()=>{if(window.experimentLocked)return;app.addComponent(type);panel.close()};
}
let materialPanel;
function material(){
 if(window.experimentLocked)return;
 if(!materialPanel){materialPanel=document.createElement('dialog');materialPanel.id='materialPanel';materialPanel.setAttribute('aria-label','添加材料');materialPanel.innerHTML='<h2>添加材料</h2><form id="materialForm"><label>材料名称<input id="materialName" maxlength="100" required placeholder="例如：石英样品"></label><label>光学行为<select id="materialMode"><option value="transmit">透射</option><option value="reflect">反射</option><option value="both">都有</option></select></label><p>添加后可在右侧调整透过率、反射率和材料参数。</p><button type="button" id="materialCancel">取消</button> <button type="submit" class="primary">＋ 放入光路</button></form>';document.body.append(materialPanel);materialPanel.addEventListener('keydown',e=>e.stopPropagation());$('materialCancel').onclick=()=>materialPanel.close();$('materialForm').onsubmit=e=>{e.preventDefault();if(window.experimentLocked)return;const name=$('materialName').value.trim();if(!name){$('materialName').focus();return;}const mode=$('materialMode').value;app.addComponent('material',{name,params:{interaction:mode,transmission:mode==='both'?50:mode==='reflect'?0:90,reflectivity:mode==='both'?50:mode==='reflect'?90:10}});materialPanel.close()};}
 $('materialName').value='材料';$('materialMode').value='transmit';materialPanel.showModal();$('materialName').focus();$('materialName').select();
}
window.ComponentPicker={open:type=>type==='material'?material():open(type)};
})();
